fn count_digits(text: &Vec<char>) -> usize {
    // Base case: if the vector is empty, return 0
    if text.is_empty() {
        return 0;
    }
    
    // Check the last character
    let last_char = text[text.len() - 1];
    // Count the digits in the rest of the vector
    let count_in_rest = count_digits(&text[..text.len() - 1].to_vec());
    
    // If the last character is a digit, increment the count
    if last_char >= '0' && last_char <= '9' {
        count_in_rest + 1
    } else {
        count_in_rest
    }
}